    ///
    /// The allocated stack might be slightly larger due to rounding necessary.
    ///
    /// Returns an error if the allocation fails, for example because the host
    /// is out of memory or `size` is infeasibly large (up to and including
    /// `usize::MAX`).
    fn new(size: usize) -> Result<Stack, OutOfMemory> {
        // Round up `size` to the nearest multiple of 16, i.e. the number of
        // `Align16` elements needed to hold `size` bytes. `div_ceil` is used to
        // avoid overflowing when `size` is very large (e.g. `usize::MAX`).
        let cap = size.div_ceil(mem::size_of::<Align16>());

        // Note that the stack is allocated here but not initialized, and that's
        // intentional as pulley bytecode should always initialize the stack
        // before use.
        let mut storage = Vec::new();
        storage
            .try_reserve_exact(cap)
            .map_err(|_| OutOfMemory::new(cap.saturating_mul(mem::size_of::<Align16>())))?;
        Ok(Stack { storage })
